#!/bin/bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "$0")/.." && pwd)"
# shellcheck source=lib/common.sh
source "$ROOT_DIR/lib/common.sh"

print_header "Stackarr Init"

DB_FILE="${STACKARR_DATABASE_FILE:-$(default_stackarr_database_file)}"
if [[ -f "$DB_FILE" ]]; then
    warn "$DB_FILE already exists."
    confirm "Overwrite Stackarr runtime config in SQLite" no || exit 0
fi

DEFAULT_APP_ROOT="$(default_app_root)"
STACKARR_REPO_ROOT="$REPO_ROOT"
DEFAULT_MEDIA="$DEFAULT_APP_ROOT/media"
DEFAULT_DOWNLOADS="$DEFAULT_APP_ROOT/downloads"
DEFAULT_BACKUPS="$DEFAULT_APP_ROOT/backups"
DEFAULT_PLEX="$HOME/Library/Application Support/Plex Media Server"
DEFAULT_PLEX_PREFS="$HOME/Library/Preferences/com.plexapp.plexmediaserver.plist"
DEFAULT_TZ="Etc/UTC"

MEDIA_ROOT="$(prompt_default 'Media root' "$DEFAULT_MEDIA")"
DEFAULT_MUSIC="$MEDIA_ROOT/Music"
MUSIC_ROOT="$(prompt_default 'Music root' "$DEFAULT_MUSIC")"
DOWNLOADS_ROOT="$(prompt_default 'Downloads root' "$DEFAULT_DOWNLOADS")"
BACKUP_ROOT="$(prompt_default 'Backup root' "$DEFAULT_BACKUPS")"
PLEX_CONFIG_PATH="$(prompt_default 'Native Plex config path' "$DEFAULT_PLEX")"
PLEX_INSTALL_MODE="$(prompt_choice 'Plex install mode (docker, native, disabled)' 'native' 'docker' 'native' 'disabled')"
JELLYFIN_INSTALL_MODE="$(prompt_choice 'Jellyfin install mode (disabled, docker, native)' 'disabled' 'disabled' 'docker' 'native')"
JELLYFIN_CONFIG_PATH="$(prompt_default 'Native Jellyfin config path' "$HOME/.local/share/jellyfin")"
if confirm "Run separate Radarr/Sonarr 4K instances" no; then ENABLE_4K_SERVARR="true"; else ENABLE_4K_SERVARR="false"; fi
if confirm "Enable Bazarr subtitles" yes; then ENABLE_BAZARR="true"; else ENABLE_BAZARR="false"; fi
if confirm "Enable Lidarr music automation" yes; then ENABLE_LIDARR="true"; else ENABLE_LIDARR="false"; fi
if confirm "Enable BookOrbit books" no; then ENABLE_BOOKORBIT="true"; else ENABLE_BOOKORBIT="false"; fi
if confirm "Enable Immich photo library functionality" no; then ENABLE_IMMICH="true"; else ENABLE_IMMICH="false"; fi
if confirm "Enable RomM private game library functionality" no; then ENABLE_ROMM="true"; else ENABLE_ROMM="false"; fi
if confirm "Enable TinyMediaManager metadata/naming" yes; then ENABLE_TINYMEDIAMANAGER="true"; else ENABLE_TINYMEDIAMANAGER="false"; fi
if confirm "Enable Recyclarr profile sync" yes; then ENABLE_RECYCLARR="true"; else ENABLE_RECYCLARR="false"; fi
if confirm "Enable FlareSolverr indexer helper" yes; then ENABLE_FLARESOLVERR="true"; else ENABLE_FLARESOLVERR="false"; fi
if confirm "Enable Tidarr Tidal helper" yes; then ENABLE_TIDARR="true"; else ENABLE_TIDARR="false"; fi
if confirm "Enable Seerr requests" no; then ENABLE_SEERR="true"; else ENABLE_SEERR="false"; fi
if flag_enabled "$ENABLE_SEERR" && confirm "Wire Seerr to Radarr/Sonarr automatically" no; then STACKARR_CONFIGURE_SEERR="true"; else STACKARR_CONFIGURE_SEERR="false"; fi
if confirm "Enable Pulsarr Plex watchlists" yes; then ENABLE_PULSARR="true"; else ENABLE_PULSARR="false"; fi
if confirm "Enable Maintainerr cleanup planner" no; then
    ENABLE_MAINTAINERR="true"
    MAINTAINERR_CLEANUP_PRESETS="$(prompt_default 'Maintainerr cleanup preset ideas (comma-separated, blank for none)' '')"
else
    ENABLE_MAINTAINERR="false"
    MAINTAINERR_CLEANUP_PRESETS=""
fi
if confirm "Enable Tracearr media-server monitoring" no; then ENABLE_TRACEARR="true"; else ENABLE_TRACEARR="false"; fi
USERNAME="$(prompt_default 'Global service username' 'admin')"
while true; do
    PASSWORD="$(prompt_secret_default 'Global service password (blank generates one)' '')"
    if [[ -z "$PASSWORD" ]] || password_is_portable "$PASSWORD"; then
        break
    fi
    warn "Global service password must be at least 8 characters and may only use letters, numbers, dot, underscore, and hyphen."
done
USER_EMAIL="$(prompt_default 'Global service email (blank uses Plex account email when available)' '')"
ROMM_LIBRARY_ROOT_INPUT=""
ROMM_METADATA_PRESET="chef"
ROMM_IGDB_CLIENT_ID=""
ROMM_IGDB_CLIENT_SECRET=""
ROMM_STEAMGRIDDB_API_KEY=""
ROMM_RETROACHIEVEMENTS_API_KEY=""
ROMM_SCREENSCRAPER_USER=""
ROMM_SCREENSCRAPER_PASSWORD=""
ROMM_HASHEOUS_API_ENABLED="true"
ROMM_PLAYMATCH_API_ENABLED="false"
if flag_enabled "$ENABLE_ROMM"; then
    ROMM_LIBRARY_ROOT_INPUT="$(prompt_default 'RomM library root' "$MEDIA_ROOT/Games")"
    ROMM_METADATA_PRESET="$(prompt_choice 'RomM metadata providers (chef, french, twitch, quick, custom)' 'chef' 'chef' 'french' 'twitch' 'quick' 'custom')"
    case "$ROMM_METADATA_PRESET" in
        chef|twitch|custom)
            ROMM_IGDB_CLIENT_ID="$(prompt_default 'RomM IGDB client ID (blank to skip)' '')"
            ROMM_IGDB_CLIENT_SECRET="$(prompt_secret_default 'RomM IGDB client secret (blank to skip)' '')"
            ;;
    esac
    case "$ROMM_METADATA_PRESET" in
        chef|custom)
            ROMM_STEAMGRIDDB_API_KEY="$(prompt_secret_default 'RomM SteamGridDB API key (blank to skip)' '')"
            ;;
    esac
    case "$ROMM_METADATA_PRESET" in
        chef|french|custom)
            ROMM_RETROACHIEVEMENTS_API_KEY="$(prompt_secret_default 'RomM RetroAchievements API key (blank to skip)' '')"
            ;;
    esac
    case "$ROMM_METADATA_PRESET" in
        french|custom)
            ROMM_SCREENSCRAPER_USER="$(prompt_default 'RomM ScreenScraper username (blank to skip)' '')"
            ROMM_SCREENSCRAPER_PASSWORD="$(prompt_secret_default 'RomM ScreenScraper password (blank to skip)' '')"
            ;;
    esac
    case "$ROMM_METADATA_PRESET" in
        quick|chef)
            ROMM_HASHEOUS_API_ENABLED="true"
            ROMM_PLAYMATCH_API_ENABLED="false"
            ;;
        twitch)
            ROMM_HASHEOUS_API_ENABLED="false"
            ROMM_PLAYMATCH_API_ENABLED="true"
            ;;
    esac
fi
