TIMEZONE="$(prompt_default 'Timezone' "$DEFAULT_TZ")"
SEERR_BIND_IP="$(prompt_default 'Seerr bind IP (0.0.0.0 for LAN, 127.0.0.1 for tunnel-only)' '0.0.0.0')"
